-- Funcionow Connect - planos, módulos e assinatura por empresa
-- O plano básico é padrão para novas empresas. BodyB recebe Master para validação.
create table if not exists public.planos (plano_id uuid primary key default gen_random_uuid(), slug text not null unique, nome text not null, descricao text, preco_mensal numeric(12,2) not null default 0, ativo boolean not null default true, criado_em timestamptz not null default now());
create table if not exists public.modulos_plataforma (modulo_id uuid primary key default gen_random_uuid(), chave text not null unique, nome text not null, descricao text not null, preco_avulso_mensal numeric(12,2) not null default 0, rota_principal text not null, ordem integer not null default 0, ativo boolean not null default true);
create table if not exists public.plano_modulos (plano_id uuid not null references public.planos(plano_id) on delete cascade, modulo_id uuid not null references public.modulos_plataforma(modulo_id) on delete cascade, preco_adicional_mensal numeric(12,2) not null default 0, primary key (plano_id, modulo_id));
create table if not exists public.empresa_assinaturas (assinatura_id uuid primary key default gen_random_uuid(), empresa_id uuid not null unique references public.empresas(empresa_id) on delete cascade, plano_id uuid not null references public.planos(plano_id), status text not null default 'ativa' check (status in ('ativa','trial','inativa','cancelada','inadimplente')), origem text not null default 'sistema', inicio_em timestamptz not null default now(), fim_em timestamptz, atualizado_em timestamptz not null default now());
insert into public.planos (slug,nome,descricao,preco_mensal) values ('basico','Plano Básico','Administração e comunidade para desenvolver creators e speakers.',0),('master','Plano Master','Acesso completo à plataforma durante a validação da BodyB.',0) on conflict (slug) do update set nome=excluded.nome,descricao=excluded.descricao;
insert into public.modulos_plataforma (chave,nome,descricao,rota_principal,ordem) values ('administracao','Administração','Configure a empresa, equipe, perfis e dados de acesso.','/dashboard',1),('comunidade','Comunidade','Cadastre, qualifique e desenvolva creators e speakers.','/creators',2),('operacao','Operação','Organize projetos, tarefas, reuniões, calendário e notas.','/operacao',3),('crescimento','Crescimento','Gerencie campanhas, Academia, Recompensas e análises.','/campanhas',4) on conflict (chave) do update set nome=excluded.nome,descricao=excluded.descricao,rota_principal=excluded.rota_principal;
insert into public.plano_modulos (plano_id,modulo_id) select p.plano_id,m.modulo_id from public.planos p join public.modulos_plataforma m on m.chave in ('administracao','comunidade') where p.slug='basico' on conflict do nothing;
insert into public.plano_modulos (plano_id,modulo_id) select p.plano_id,m.modulo_id from public.planos p cross join public.modulos_plataforma m where p.slug='master' on conflict do nothing;
create or replace function public.atribuir_plano_basico_empresa() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.empresa_assinaturas (empresa_id,plano_id,status,origem) select new.empresa_id,plano_id,'ativa','cadastro_empresa' from public.planos where slug='basico' on conflict (empresa_id) do nothing; return new; end; $$;
drop trigger if exists trg_empresa_plano_basico on public.empresas;
create trigger trg_empresa_plano_basico after insert on public.empresas for each row execute function public.atribuir_plano_basico_empresa();
insert into public.empresa_assinaturas (empresa_id,plano_id,status,origem) select e.empresa_id,p.plano_id,'ativa','cadastro_empresa' from public.empresas e join public.planos p on p.slug='basico' where not exists (select 1 from public.empresa_assinaturas a where a.empresa_id=e.empresa_id) on conflict (empresa_id) do nothing;
update public.empresa_assinaturas a set plano_id=p.plano_id,status='ativa',origem='validacao_bodyb',atualizado_em=now() from public.empresas e join public.planos p on p.slug='master' where a.empresa_id=e.empresa_id and lower(regexp_replace(e.nome,'[^a-zA-Z0-9]','','g')) like '%bodyb%';
alter table public.planos enable row level security; alter table public.modulos_plataforma enable row level security; alter table public.plano_modulos enable row level security; alter table public.empresa_assinaturas enable row level security;
drop policy if exists "planos_select_authenticated" on public.planos; create policy "planos_select_authenticated" on public.planos for select to authenticated using (ativo=true);
drop policy if exists "modulos_select_authenticated" on public.modulos_plataforma; create policy "modulos_select_authenticated" on public.modulos_plataforma for select to authenticated using (ativo=true);
drop policy if exists "plano_modulos_select_authenticated" on public.plano_modulos; create policy "plano_modulos_select_authenticated" on public.plano_modulos for select to authenticated using (true);
drop policy if exists "empresa_assinaturas_select_empresa" on public.empresa_assinaturas; create policy "empresa_assinaturas_select_empresa" on public.empresa_assinaturas for select to authenticated using (exists (select 1 from public.usuarios u where u.usuario_id=auth.uid() and u.empresa_id=empresa_assinaturas.empresa_id));
grant select on public.planos,public.modulos_plataforma,public.plano_modulos,public.empresa_assinaturas to authenticated;
grant select,insert,update,delete on public.planos,public.modulos_plataforma,public.plano_modulos,public.empresa_assinaturas to service_role;

